import "../Styles/StudentLogin.css";
import {
  Button,
  Col,
  Container,
  Row,
  FormGroup,
  Input,
  Form,
  Label,
} from "reactstrap";
import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

const StudentLogin = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [errorMsg, setErrorMsg] = useState("");

  const handleLogin = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch("http://localhost:3001/studentlogin", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      const data = await response.json();

      if (!response.ok) {
        setErrorMsg(data.msg || "Login failed");
        return;
      }

      // ✅ Save user info
      localStorage.setItem("userData", JSON.stringify(data.user));

      // ✅ Redirect depending on role
      if (data.user.role === "Student") navigate("/home");
      else navigate("/company-dashboard");
    } catch (error) {
      setErrorMsg("Server error. Try again later.");
    }
  };

  return (
    <Container fluid className="login-container">
      <div className="login-box">
        <h2>
          Welcome <span>Back</span>
        </h2>
        <p className="login-subtext">Please enter your email and password</p>

        <Form onSubmit={handleLogin}>
          <Row>
            <Col md={12}>
              <FormGroup>
                <Label for="email" className="input-label">
                  Email
                </Label>
                <Input
                  id="email"
                  name="email"
                  placeholder="Enter your Email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
          </Row>

          <Row>
            <Col md={12}>
              <FormGroup>
                <Label for="password" className="input-label">
                  Password
                </Label>
                <Input
                  id="password"
                  name="password"
                  placeholder="Enter your Password"
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
          </Row>

          <Row>
            <Col md={12}>
              <Button className="login-btn" type="submit">
                Login
              </Button>
            </Col>
          </Row>

          {errorMsg && (
            <Row>
              <Col md={12}>
                <p className="error-text">{errorMsg}</p>
              </Col>
            </Row>
          )}

          <Row>
            <Col md={12}>
              <p className="smalltext">
                No Account? <Link to="/studentregister">Sign up now</Link>
              </p>
            </Col>
          </Row>
        </Form>
      </div>
    </Container>
  );
};

export default StudentLogin;
